using System.Text.Json;
using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class ReadAuditMethods{
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));
    private static CompiledSource Compile(string type="Queries")=>new RuntimeCompiler().Compile(new("1",[new("query.cs","using System.Linq;namespace AuditReadSample;public static class "+type+"{static "+type+"(){throw new System.InvalidOperationException(\"DO_NOT_EXECUTE\");}public static int Run(int[] values){var HiddenBudgetPolicy=1234567;return values.Where(value=>value>HiddenBudgetPolicy).Sum();}}")],[]),entryType:"AuditReadSample."+type,entryMember:"Run");
    private static AuditReadKey Key(string artifact){var at=new DateTimeOffset(2026,11,4,0,0,0,TimeSpan.Zero);return new(at,at.AddMinutes(1),Guid.NewGuid(),"user","sales","opaque-id",artifact,null);}
    private static void Register(ManagementStore store,CompiledSource compiled){Assert.NotEmpty(compiled.AssemblyBytes);store.Write(()=>store.Put("queryAudit",compiled.Result.ArtifactHash,compiled.AuditMetadata!));}
    private static JsonElement Method(AuditReadEntry entry){var json=JsonSerializer.SerializeToElement(entry,ManagementJson.Options);Assert.True(json.TryGetProperty("method",out var method),"呼出し元メソッドの情報がありません。");return method;}
    [Fact]public void QualifiedNameAndCrossFieldAndSearchUseTheOriginalMethod(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");var compiled=Compile();Register(store,compiled);store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(compiled.Result.ArtifactHash),3)]);var item=Assert.Single(store.ReadSummaries(new(Text:"auditreadsample.queries.run sales")).Items);var method=Method(item);Assert.Equal("AuditReadSample",method.GetProperty("namespace").GetString());Assert.Equal("Queries",method.GetProperty("typeName").GetString());Assert.Equal("Run",method.GetProperty("methodName").GetString());Assert.Equal(compiled.AuditMetadata!.ModuleId,method.GetProperty("moduleId").GetGuid());Assert.Equal(compiled.AuditMetadata.MetadataToken,method.GetProperty("metadataToken").GetInt32());Assert.Contains("values",method.GetProperty("methodSignature").GetString()!);Assert.Empty(store.ReadSummaries(new(Text:"AuditReadSample missing")).Items);}
    [Fact]public void TemplateAccessCannotBeInferredBySearchWithoutSourcePermission(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");var compiled=Compile();Register(store,compiled);store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(compiled.Result.ArtifactHash),1)]);using var service=new Seamless.Management.Server.ManagementService(store);var manager=new UserAccount("manager","",[new("*",ManagementPermission.Manage)]);var restricted=Assert.Single(service.ReadSummaries(manager,new(Text:"AuditReadSample.Queries.Run")).Items);Assert.Equal(JsonValueKind.Null,Method(restricted).GetProperty("queryTemplate").ValueKind);Assert.Empty(service.ReadSummaries(manager,new(Text:"HiddenBudgetPolicy")).Items);var developer=manager with{Grants=[..manager.Grants,new("sales",ManagementPermission.Edit)]};var visible=Assert.Single(service.ReadSummaries(developer,new(Text:"Queries.Run HiddenBudgetPolicy")).Items);var template=Method(visible).GetProperty("queryTemplate").GetString()!;Assert.Contains("HiddenBudgetPolicy",template);Assert.DoesNotContain("1234567",template);Assert.DoesNotContain("DO_NOT_EXECUTE",template);}
    [Fact]public void OlderArtifactsKeepTheirNamesAndMissingMetadataIsExplicit(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");var old=Compile("OldQueries");var current=Compile("NewQueries");Register(store,old);Register(store,current);store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(old.Result.ArtifactHash),10),new(Key(current.Result.ArtifactHash),20),new(Key("unregistered"),1)]);Assert.Equal(10,Assert.Single(store.ReadSummaries(new(Text:"OldQueries.Run")).Items).Count);Assert.Equal(20,Assert.Single(store.ReadSummaries(new(Text:"NewQueries.Run")).Items).Count);var missing=Assert.Single(store.ReadSummaries(new(Text:"unregistered")).Items);Assert.Equal(JsonValueKind.Null,Method(missing).ValueKind);}
    [Fact]public void MismatchedMetadataIsRejectedInsteadOfShowingAnotherArtifact(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");var compiled=Compile();store.Write(()=>store.Put("queryAudit",compiled.Result.ArtifactHash,compiled.AuditMetadata! with{ArtifactHash=new string('0',64)}));store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(compiled.Result.ArtifactHash),1)]);Assert.Throws<InvalidDataException>(()=>store.ReadSummaries(new()));}
    [Fact]public void TemplateSearchStopsAtTheCharacterBudgetAndKeepsTheCursor(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");var compiled=Compile();store.Write(()=>store.Put("queryAudit",compiled.Result.ArtifactHash,compiled.AuditMetadata! with{QueryTemplate=new string('x',8192)}));var key=Key(compiled.Result.ArtifactHash);store.ApplyReadSummaryBatch(Guid.NewGuid(),Enumerable.Range(0,300).Select(index=>new AuditReadDelta(key with{QueryId="q"+index},1)).ToArray());var first=store.ReadSummaries(new(Text:"absent"));Assert.Empty(first.Items);Assert.True(first.HasMore);Assert.InRange(first.Examined,1,299);Assert.True(first.NextBefore>0);var restricted=store.ReadSummaries(new(Text:"absent"),static _=>false);Assert.Empty(restricted.Items);Assert.False(restricted.HasMore);Assert.Equal(300,restricted.Examined);}
}
